import { PostgresDriver, RedisDriver, PulsarUnifiedStorage } from "@nightx.co/pulsar-client/storage";
import { HttpWorker } from "@nightx.co/pulsar-client/class";
import "dotenv/config";

const cacheStorage = new RedisDriver({
    protocol : "tcp",
    connectionString : process.env.REDIS_TCP as string,
})

const postgresDriver = new PostgresDriver({
    connectionString: process.env.POSTGRESSQL_TCP as string,
    connectionProtocol : "tcp"
})

const unifiedStorage = new PulsarUnifiedStorage({
    cache : cacheStorage,
    db : postgresDriver,
    strategy : "AUTO",
})

const queue = "q_2";
const apiKey = 'MMvGnFbCs7gpFaO31SOmvz4b82jEp1SVfoKLUAIIivqGXPoVDDeycjDfdwAOIkwx'

export const worker = new HttpWorker(queue, {
    apiKey,
    storage : unifiedStorage,
    concurrency : 1,
});